{
  "sop_id": "SOP-020",
  "title": "Leave applications (HR)",
  "steps": [
    {
      "step_id": "S1",
      "name": "Create leave ticket",
      "role": "Executor",
      "type": "intake"
    },
    {
      "step_id": "S2",
      "name": "Assign ticket to Executor",
      "role": "Executor",
      "type": "intake"
    },
    {
      "step_id": "S3",
      "name": "Check leave balance and eligibility",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S4",
      "name": "Record dates (excluding holidays and weekly offs)",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S5",
      "name": "Submit leave application",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "A1",
      "name": "Incharge approval/rejection",
      "role": "Incharge",
      "type": "approval"
    },
    {
      "step_id": "R1",
      "name": "Rework if rejected",
      "role": "Executor",
      "type": "rework"
    },
    {
      "step_id": "A2",
      "name": "Lead approval (for >10 days or medical >2 days)",
      "role": "Lead",
      "type": "approval"
    }
  ],
  "approvals": [
    {
      "stage": "Incharge",
      "condition": "always"
    },
    {
      "stage": "Lead",
      "condition": "Leave duration > 10 days OR medical leave > 2 days"
    }
  ],
  "dependencies": [],
  "rework_reasons": [
    "Wrong quantity",
    "Amount mismatch",
    "Incorrect category",
    "Required document missing"
  ],
  "first_pass_yield_target": 0.95
}
